    if ns_zeros == 0 or ns_zeros == 5:
        # No change - copy test row
        output_row = test_row[:]
    else:
        # Find matching demo row with same zero count
        demo_match = None
        for d in range(13):
            if get_ns_zero_count(demo_in[d]) == ns_zeros:
                demo_match = d
                break
        if demo_match is not None:
            output_row = demo_out[demo_match][:]
        else:
            output_row = test_row[:]

    output_grid.append(output_row)

# Convert to string format
grid_str = '\n'.join([', '.join(map(str, row)) for row in output_grid])

grid_list = output_grid

print("Output grid:")
